biweekly-contest-108-longest-alternating:
{
  "problem_id": "alternating_subarray",
  "nodes": [
    {
      "id": 1,
      "type": "start",
      "label": "Start",
      "next": 2
    },
    {
      "id": 2,
      "type": "process",
      "label": "Input: nums (array of integers)",
      "action": "ctx['nums'] = ctx['arg0']; ctx['ans'] = -1; ctx['i'] = 0",
      "next": 4
    },
    {
      "id": 4,
      "type": "decision",
      "label": "Iterate i from 1 to len(nums)-1",
      "logic": "ctx['i'] < len(ctx['nums']) - 1",
      "true_next": 5,
      "false_next": 11
    },
    {
      "id": 5,
      "type": "process",
      "label": "Iterate j from i to len(nums)-1",
      "action": "ctx['j'] = ctx['i'] + 1; ctx['l'] = 2",
      "next": 7
    },
    {
      "id": 7,
      "type": "decision",
      "label": "Is j < len(nums) AND nums[j] - nums[j - 1] == (-1)^l?",
      "logic": "ctx['j'] < len(ctx['nums']) and (ctx['nums'][ctx['j']] - ctx['nums'][ctx['j'] - 1] == pow(-1, ctx['l']))",
      "true_next": 8,
      "false_next": 12
    },
    {
      "id": 8,
      "type": "process",
      "label": "Update ans: ans = max(ans, l)",
      "action": "ctx['ans'] = max(ctx['ans'], ctx['l'])",
      "next": 9
    },
    {
      "id": 9,
      "type": "process",
      "label": "Increment j: j += 1",
      "action": "ctx['j'] += 1",
      "next": 10
    },
    {
      "id": 10,
      "type": "process",
      "label": "Increment l: l += 1",
      "action": "ctx['l'] += 1",
      "next": 7
    },
    {
      "id": 12,
      "type": "process",
      "label": "Exit inner loop (break)",
      "action": "ctx['i'] += 1",
      "next": 4
    },
    {
      "id": 11,
      "type": "end",
      "label": "Output: ans (maximum length of alternating subarrays or -1)",
      "output": "ctx['ans']"
    }
  ]
}

