      "label": "Initialize N = length of nums",
      "action": "ctx['N'] = len(ctx['nums'])",
      "next": 4
    },
    {
      "id": 4,
      "type": "process",
      "label": "Initialize pref as a list of zeros with length N",
      "action": "ctx['pref'] = [0] * ctx['N']",
      "next": 5
    },
    {
      "id": 5,
      "type": "process",
      "label": "Set pref[0] = nums[0]",
      "action": "ctx['pref'][0] = ctx['nums'][0]",
      "next": 6
    },
    {
      "id": 6,
      "type": "process",
      "label": "Initialize lastEven = 0, lastOdd = 0",
      "action": "ctx['lastEven'] = 0; ctx['lastOdd'] = 0; ctx['i'] = 1",
      "next": 7
    },
    {
      "id": 7,
      "type": "decision",
      "label": "For i from 1 to N-1",
      "logic": "ctx['i'] < ctx['N']",
      "true_next": 8,
      "false_next": 13
    },
    {
      "id": 8,
      "type": "process",
      "label": "Calculate pref[i] = pref[lastEven] + nums[i] - (((nums[lastEven] + nums[i]) % 2) * x)",
      "action": "ctx['pref'][ctx['i']] = ctx['pref'][ctx['lastEven']] + ctx['nums'][ctx['i']] - (((ctx['nums'][ctx['lastEven']] + ctx['nums'][ctx['i']]) % 2) * ctx['x'])",
      "next": 9
