      "action": "ctx['pref'][ctx['i']] = max(ctx['pref'][ctx['i']], ctx['pref'][ctx['lastOdd']] + ctx['nums'][ctx['i']] - (((ctx['nums'][ctx['lastOdd']] + ctx['nums'][ctx['i']]) % 2) * ctx['x']))",
