    },
    {
      "id": 11,
      "type": "process",
      "label": "Set lastOdd = i",
      "action": "ctx['lastOdd'] = ctx['i']; ctx['i'] += 1",
      "next": 7
    },
    {
      "id": 12,
      "type": "process",
      "label": "Set lastEven = i",
      "action": "ctx['lastEven'] = ctx['i']; ctx['i'] += 1",
      "next": 7
    },
    {
