biweekly-contest-109-ways-to-express-an-:
{
  "problem_id": "numberOfWays",
  "nodes": [
    {
      "id": 1,
      "type": "start",
      "label": "Start",
      "next": 2
    },
    {
      "id": 2,
      "type": "process",
      "label": "Input: n (integer), x (integer)",
      "action": "ctx['n'] = ctx['arg0']; ctx['x'] = ctx['arg1']; ctx['mod'] = 10**9 + 7; ctx['dp'] = [0] * (ctx['n'] + 1); ctx['dp'][0] = 1; ctx['ans'] = [i**ctx['x'] for i in range(1, ctx['n'] + 1) if i**ctx['x'] <= ctx['n']]; ctx['L'] = len(ctx['ans']); ctx['i'] = ctx['L'] - 1",
      "next": 3
    },
    {
      "id": 3,
      "type": "decision",
      "label": "For i from L - 1 to 0 (inclusive)",
      "logic": "ctx['i'] >= 0",
      "true_next": 4,
      "false_next": 10
    },
    {
      "id": 4,
      "type": "process",
      "label": "Initialize dpn as list of zeros with length (n + 1)",
      "action": "ctx['dpn'] = [0] * (ctx['n'] + 1); ctx['j'] = 0",
      "next": 5
    },
    {
      "id": 5,
      "type": "decision",
      "label": "For j from 0 to n",
      "logic": "ctx['j'] <= ctx['n']",
      "true_next": 6,
      "false_next": 9
    },
    {
      "id": 6,
      "type": "process",
      "label": "Set dpn[j] = dp[j]",
      "action": "ctx['dpn'][ctx['j']] = ctx['dp'][ctx['j']]",
      "next": 7
    },
    {
      "id": 7,
      "type": "decision",
      "label": "Is j - ans[i] >= 0?",
      "logic": "ctx['j'] - ctx['ans'][ctx['i']] >= 0",
      "true_next": 8,
      "false_next": 11
    },
    {
      "id": 8,
      "type": "process",
      "label": "Update dpn[j]: dpn[j] += dp[j - ans[i]]",
      "action": "ctx['dpn'][ctx['j']] = (ctx['dpn'][ctx['j']] + ctx['dp'][ctx['j'] - ctx['ans'][ctx['i']]]) % ctx['mod']",
      "next": 11
    },
    {
      "id": 11,
      "type": "process",
      "label": "Continue to next j",
      "action": "ctx['j'] += 1",
      "next": 5
    },
    {
      "id": 9,
      "type": "process",
      "label": "Update dp: dp = dpn",
      "action": "ctx['dp'] = list(ctx['dpn']); ctx['i'] -= 1",
      "next": 3
    },
    {
      "id": 10,
      "type": "end",
      "label": "Output: dp[n] % mod",
      "output": "ctx['dp'][ctx['n']] % ctx['mod']"
    }
  ]
}

