weekly-contest-381-count-the-number-of-h:
{
  "problem_id": "count_of_pairs",
  "nodes": [
    {
      "id": 1,
      "type": "start",
      "label": "Start",
      "next": 2
    },
    {
      "id": 2,
      "type": "process",
      "label": "Input: n (integer), x (integer), y (integer)",
      "action": "ctx['n']=ctx['arg0']; ctx['x']=ctx['arg1']; ctx['y']=ctx['arg2']; ctx['mi']=min(ctx['x'], ctx['y'])-1; ctx['ma']=max(ctx['x'], ctx['y'])-1; ctx['res']=[0]*ctx['n']; ctx['i']=0",
      "next": 6
    },
    {
      "id": 6,
      "type": "decision",
      "label": "Loop i from 0 to n-2",
      "logic": "ctx['i'] < ctx['n'] - 1",
      "true_next": 7,
      "false_next": 11
    },
    {
      "id": 7,
      "type": "process",
      "label": "Loop j from i+1 to n-1",
      "action": "ctx['j'] = ctx['i'] + 1",
      "next": 7_loop_check
    },
    {
      "id": 7_loop_check,
      "type": "decision",
      "label": "Loop j condition",
      "logic": "ctx['j'] < ctx['n']",
      "true_next": 8,
      "false_next": 10
    },
    {
      "id": 8,
      "type": "process",
      "label": "Calculate dis = min(j - i, abs(mi - i) + abs(ma - j) + 1)",
      "action": "ctx['dis'] = min(ctx['j'] - ctx['i'], abs(ctx['mi'] - ctx['i']) + abs(ctx['ma'] - ctx['j']) + 1)",
      "next": 9
    },
    {
      "id": 9,
      "type": "process",
      "label": "Update res[dis - 1] += 2",
      "action": "ctx['res'][ctx['dis'] - 1] += 2; ctx['j'] += 1",
      "next": 7_loop_check
    },
    {
      "id": 10,
      "type": "process",
      "label": "End Loop i",
      "action": "ctx['i'] += 1",
      "next": 6
    },
    {
      "id": 11,
      "type": "end",
      "label": "Output: res (list of integers)",
      "output": "ctx['res']"
    }
  ]
}

